package game.agent.web;
import game.agent.persistence.*;import game.agent.eval.*;import game.agent.llm.*;import java.nio.file.*;import java.util.*;
public class V5LiveReloadVerification {public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);for(String mode:Arrays.asList("manual","delegated","auto")){Map<String,Object> original=Json.asObject(Json.read(new String(Files.readAllBytes(root.resolve(mode+".json")),java.nio.charset.StandardCharsets.UTF_8)));try(WorldStore store=new FileWorldStore(root.resolve("saves-"+mode))){DuelRoom room=new DuelRoom("live-"+mode,new ProviderSelection("disabled","none",1000,null,null),new EvaluationProviders(Collections.singletonList("baseline"),1000,m->DuelRoom::baseline),Runnable::run,store,Collections::emptyList);Map<String,Object> saved=room.snapshot();for(String field:Arrays.asList("status","world","trace","decisions","tokens","calls","usageIncomplete"))if(!Json.write(original.get(field)).equals(Json.write(saved.get(field))))throw new IllegalStateException("RELOAD_MISMATCH_"+field);System.out.println(mode+": saved battle reload verified; no API call");room.close();}}}}
